use vstd::prelude::*;

verus! {

fn concatenate(a: Vec<f32>, b: Vec<f32>) -> (res: Vec<f32>)
    ensures
        res@.len() == a@.len() + b@.len(),
        forall|i: int|
            0 <= i < a@.len() ==> res@[i] == a@[i],
        forall|j: int|
            0 <= j < b@.len() ==> res@[a@.len() + j] == b@[j],
{
    let mut res: Vec<f32> = Vec::new();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            0 <= i as int <= a@.len(),
            res@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> res@[k] == a@[k],
        decreases a.len() - i,
    {
        res.push(a[i]);
        i += 1;
    }

    let a_len: usize = a.len();

    let mut j: usize = 0;
    while j < b.len()
        invariant
            a_len as int == a@.len(),
            0 <= j as int <= b@.len(),
            res@.len() == a@.len() + j as int,
            forall|k: int| 0 <= k < a@.len() ==> res@[k] == a@[k],
            forall|t: int| 0 <= t < j as int ==> res@[a@.len() + t] == b@[t],
        decreases b.len() - j,
    {
        res.push(b[j]);
        j += 1;
    }

    res
}

} // verus!

